style.css:
@-moz-document domain("websim.com"), domain("www.websim.com") {
html, body {
    background-color: #0b0e11 !important;
    color: #eef2f8 !important;
  }

  /* Panels & cards */
  div, section, article, aside, .card, .panel, .container, .modal, .popover, .dropdown, .sidebar {
    background-color: #111418 !important;
    color: #eef2f8 !important;
    border: 1px solid #232933 !important;
  }

  /* Headers & navbars */
  header, nav, .topbar {
    background: #0d1116 !important;
    border-bottom: 1px solid #232933 !important;
  }

  /* Paragraphs & text */
  p, span, div, label, li, small {
    color: #c7d0dc !important;
  }
  h1, h2, h3, h4, h5 {
    color: #eef2f8 !important;
  }

  /* Links */
  a {
    color: #7c5cff !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline !important;
  }

  /* Buttons */
  button, .btn, [role="button"] {
    background: #1c2030 !important;
    color: #eef2f8 !important;
    border: 1px solid #232933 !important;
    border-radius: 6px !important;
  }
  button:hover, .btn:hover {
    background: #292f47 !important;
  }

  /* Inputs & textareas */
  input, textarea, select {
    background-color: #171b20 !important;
    color: #eef2f8 !important;
    border: 1px solid #232933 !important;
  }
  input::placeholder, textarea::placeholder {
    color: #8b97a8 !important;
  }

  /* Code blocks */
  pre, code {
    background-color: #0f1319 !important;
    color: #e7ecf4 !important;
    border: 1px solid #232933 !important;
  }

  /* Tables */
  table {
    background-color: #111418 !important;
    border-color: #232933 !important;
  }
  th, td {
    border-color: #232933 !important;
    color: #c7d0dc !important;
  }
  tr:nth-child(even) {
    background-color: #141922 !important;
  }

  /* Scrollbars */
  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }
  *::-webkit-scrollbar-track {
    background: #0e1116 !important;
  }
  *::-webkit-scrollbar-thumb {
    background: #3a4352 !important;
    border-radius: 10px;
    border: 2px solid #0e1116 !important;
  }

  /* Overlays */
  .modal-backdrop, .overlay, .backdrop {
    background: rgba(0, 0, 0, 0.55) !important;
  }
}
